    resolveGoalPoint(goal,grid){if(!grid)return goal;const entity=this.sceneEntities().find(e=>String(e.id)===String(goal.semanticId||goal.targetId));const radius=this.profile().width/2;if(entity&&Number.isFinite(entity.w)&&Number.isFinite(entity.d)){const samples=[{x:entity.x+entity.w/2+radius+.28,z:entity.z},{x:entity.x-entity.w/2-radius-.28,z:entity.z},{x:entity.x,z:entity.z+entity.d/2+radius+.28},{x:entity.x,z:entity.z-entity.d/2-radius-.28}];const candidates=samples.map(p=>{const i=grid.nearest(p,.8);return i>=0?grid.point(i):null;}).filter(Boolean).filter(p=>grid.isClear(p.x,p.z,radius));if(candidates.length)return candidates.sort((a,b)=>Math.hypot(a.x-goal.x,a.z-goal.z)-Math.hypot(b.x-goal.x,b.z-goal.z))[0];}const near=grid.nearest(goal,.8);return near>=0?grid.point(near):goal;}
    destinationQueue(){const state=this.api.state(),model=state.model,grid=state.grid;if(!model)return[];let source=this.schedule.length?this.schedule:(model.goals||[]);if(!source.length&&!this.schedule.length&&!model.editableHome){const entities=this.sceneEntities().filter(e=>e.kind!=='door'&&e.kind!=='goal'&&Number.isFinite(e.x)&&Number.isFinite(e.z));const priority=e=>/bed|床|sofa|沙发|fridge|冰箱|toilet|卫生间|chair|椅|table|桌|cabinet|柜/i.test(`${e.kind} ${e.name}`)?0:1;source=entities.sort((a,b)=>priority(a)-priority(b)).slice(0,12).map((e,i)=>({id:`auto-${i+1}`,semanticId:e.id,name:e.name||`自动识别对象 ${i+1}`,x:e.x,z:e.z,source:'auto-recognized'}));}const queue=source.filter(g=>Number.isFinite(Number(g.x))&&Number.isFinite(Number(g.z))).map((g,i)=>{const p=this.resolveGoalPoint(g,grid);return{...g,id:g.id??`destination-${i+1}`,name:g.name||`目的地 ${i+1}`,x:p.x,z:p.z,source:g.source||'default'};});const articulated=L.modelReplacement?.articulatedDestinations?.()||[];for(const goal of articulated){const duplicate=queue.some(item=>String(item.semanticId??item.furnitureTarget??'')===String(goal.semanticId??goal.furnitureTarget??''));if(duplicate)continue;const p=this.resolveGoalPoint(goal,grid);if(!Number.isFinite(p?.x)||!Number.isFinite(p?.z))continue;queue.push({...goal,x:p.x,z:p.z,source:goal.source||'articulated-furniture'});}return queue;}
