    renderQueue(){const queue=this.destinationQueue();$('resident-task-list').innerHTML=queue.length?queue.map((goal,index)=>`<div class="task-queue-row"><span>${index+1}</span><div><b>${esc(goal.name)}</b><small>${goal.sourceLabel?esc(goal.sourceLabel)+' · ':''}${goal.time?esc(goal.time)+' · ':''}${goal.x.toFixed(2)}, ${goal.z.toFixed(2)} m</small></div></div>`).join(''):'<p class="hint">暂无目的地，请在上方添加，或在 DIY 中输入“床 → 冰箱 → 卫生间”。</p>';}
